// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testRegression_property() public {
        c.createGameItem("Item0", "uri0", false, true, 100, 1, 10);
        c.createGameItem("Item1", "uri1", true, false, 50, 2, 5);
        c.createGameItem("Item2", "uri2", false, true, 200, 0, 20);

        uint256 bal = c.balanceOf(address(this), 3);

        assertTrue(bal == 0, "balanceOf for non-existent token should be 0");
    }
}
